from pathlib import Path
import sys,re
from urllib.parse import urljoin
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tools'))
from lib.learn_catalogue_v3 import render_catalogue
indian=[(s,c,n,t,[],[],[],[]) for s,c,n,t in [('bengali','bn','Bengali','বাংলা'),('gujarati','gu','Gujarati','ગુજરાતી'),('marathi','mr','Marathi','मराठी'),('punjabi','pa','Punjabi','ਪੰਜਾਬੀ'),('tamil','ta','Tamil','தமிழ்'),('telugu','te','Telugu','తెలుగు'),('urdu','ur','Urdu','اردو')]]
world=[(c,n,t,'languages/'+c+'/course',[],[],[]) for c,n,t in [('ar','Arabic','العربية'),('de','German','Deutsch'),('es','Spanish','español'),('fr','French','français'),('it','Italian','italiano'),('ja','Japanese','日本語'),('ko','Korean','한국어'),('pt','Portuguese','português'),('ru','Russian','Русский'),('zh','Chinese','中文')]]
def href(target):return target[6:]+'/' if target.startswith('learn/') else '../'+target+'/'
old=''.join(f'<a href="{u}">{l}</a>' for u,l in [('hindi/foundation/','Hindi foundation'),('hindi-alphabet-for-beginners/','Hindi alphabet'),('paths/hindi-from-zero/','Hindi from zero'),('../daily-hindi/','Daily Hindi'),('./spanish/','Spanish guides'),('./arabic/','Arabic guides'),('./german/','German guides'),('../name-in-hindi/','Write your name in Hindi')])
region=render_catalogue(indian,world,{},old,href)
# Preview only: educational destinations go to the current live site. CSS and images are local.
region=re.sub(r'href="([^"]+)"',lambda m:'href="'+(m[1][3:] if m[1].startswith('../css/') else urljoin('https://ekguru.shop/learn/',m[1]))+'"',region)
region=region.replace('src="../js/','src="js/').replace('src="../images/','src="images/')
html='''<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>EkGuru — Learn preview</title><style>html{color-scheme:light}body{margin:0;font-family:Inter,'Noto Sans','Noto Sans Devanagari',system-ui,sans-serif;color:#18342e;background:#fafbf7}html[data-theme=dark]{color-scheme:dark;background:#121d17;--ink:#eaf5eb;--muted:#b3c5bb}html[data-theme=dark] body{background:#121d17;color:#eaf5eb}*{box-sizing:border-box}.preview-header{border-bottom:1px solid #d9e2dc;background:inherit}.preview-header nav{max-width:1340px;padding:14px clamp(16px,4vw,48px);display:flex;align-items:center;justify-content:space-between;margin:auto;gap:14px}.brand{display:flex;align-items:center;gap:9px;font-weight:800;font-size:1.2rem;color:inherit;text-decoration:none}.mark{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#183e35;color:#f4d58b;font-size:1.1rem}.preview-nav{display:flex;align-items:center;gap:20px;font-size:.88rem}.preview-nav a{color:inherit;text-decoration:none}.preview-nav button{font:inherit;min-height:44px;background:transparent;color:inherit;border:1px solid #9ba99f;border-radius:8px;padding:6px 12px;cursor:pointer}.lw{max-width:1340px;margin:auto;padding-bottom:30px}.crumb{font-size:.8rem;color:#65746d;margin:24px 0 0}.crumb a{color:inherit}.kicker{font-size:.73rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted,#52635d);font-weight:700}.preview-footer{border-top:1px solid #d9e2dc;text-align:center;padding:22px;font-size:.8rem;color:var(--muted,#52635d)}@media(max-width:520px){.preview-nav a{display:none}}</style><link rel="stylesheet" href="css/learn-catalogue-v3.css"></head><body><header class="preview-header"><nav><a class="brand" href="https://ekguru.shop/"><span class="mark">ए</span>EkGuru</a><div class="preview-nav"><a href="https://ekguru.shop/learn/">Learn</a><a href="https://ekguru.shop/find-tutors.html">Tutors</a><button id="theme" type="button">Dark mode</button></div></nav></header><main id="main"><div class="lw"><p class="crumb"><a href="https://ekguru.shop/">Home</a> / Learn</p><div class="hero"><span class="kicker">Learn · Free self-paced materials</span><h1>Choose a language.</h1></div>'''+region+'''</div></main><footer class="preview-footer">Design preview · Course links open current EkGuru website</footer><script>document.getElementById('theme').onclick=()=>{let d=document.documentElement;d.dataset.theme=d.dataset.theme==='dark'?'light':'dark';document.getElementById('theme').textContent=d.dataset.theme==='dark'?'Light mode':'Dark mode';};</script></body></html>'''
(ROOT/'preview.html').write_text(html,encoding='utf-8')
# Fully self-contained preview, reproducible with the same renderer.
import base64
css=(ROOT/'css/learn-catalogue-v3.css').read_text()
js=(ROOT/'js/learn-catalogue-v3.js').read_text()
art=base64.b64encode((ROOT/'images/learn-catalogue/hindi-book.svg').read_bytes()).decode()
html=html.replace('<link rel="stylesheet" href="css/learn-catalogue-v3.css">','<style>'+css+'</style>').replace('<script src="js/learn-catalogue-v3.js" defer></script>','').replace('src="images/learn-catalogue/hindi-book.svg"','src="data:image/svg+xml;base64,'+art+'"').replace('</body>','<script>'+js+'</script></body>')
(ROOT/'preview-standalone.html').write_text(html,encoding='utf-8')
